/* Smoke test for src/js/planner.js.
   Loads hours.js and planner.js into a vm context with a hand-rolled window/document stub
   (jsdom is not installed and nothing may be installed), then exercises the pure logic. */
import fs from 'node:fs';
import path from 'node:path';
import vm from 'node:vm';
import assert from 'node:assert/strict';
import { fileURLToPath } from 'node:url';

const ROOT = 'C:/Users/Kenneth Rodas/Documents/GitHub/eatdanville';
const read = (p) => fs.readFileSync(path.join(ROOT, p), 'utf8');
const json = (p) => JSON.parse(read(p));

const restaurants = json('data/restaurants.json');
const site = json('data/district.json');
const categories = json('data/categories.json');

// ---------- DOM stub ----------
let lastBlob = null;
let dispatched = [];
let copied = null;

function fakeNode(tag) {
  return {
    tag,
    href: '',
    attrs: {},
    listeners: {},
    style: {},
    value: '',
    dataset: {},
    setAttribute(k, v) { this.attrs[k] = String(v); },
    getAttribute(k) { return Object.prototype.hasOwnProperty.call(this.attrs, k) ? this.attrs[k] : null; },
    addEventListener(t, f) { (this.listeners[t] = this.listeners[t] || []).push(f); },
    removeEventListener() {},
    click() { (this.listeners.click || []).forEach((f) => f({ preventDefault() {}, target: this })); },
    select() {},
    contains() { return true; },
    closest() { return null; },
    querySelector() { return null; },
    querySelectorAll() { return []; },
    appendChild() {},
    removeChild() {},
    focus() {},
  };
}

const resultNodes = {
  '[data-plan-ics]': fakeNode('a'),
  '[data-plan-copy]': fakeNode('button'),
  '[data-plan-share]': fakeNode('button'),
};
const resultEl = {
  innerHTML: '',
  attrs: {},
  setAttribute(k, v) { this.attrs[k] = v; },
  getAttribute(k) { return this.attrs[k] || null; },
  querySelector(sel) { return resultNodes[sel] || null; },
  querySelectorAll(sel) { return resultNodes[sel] ? [resultNodes[sel]] : []; },
};

const ctx = {
  console,
  setTimeout,
  clearTimeout,
  navigator: {
    clipboard: { writeText: (t) => { copied = t; return Promise.resolve(); } },
  },
  Blob: class Blob {
    constructor(parts, opts) { lastBlob = { text: parts.join(''), type: opts && opts.type }; }
  },
  URL: {
    createObjectURL: () => 'blob:eat-danville-fake',
    revokeObjectURL: () => {},
  },
  document: {
    readyState: 'complete',
    body: fakeNode('body'),
    documentElement: { classList: { contains: () => false } },
    querySelectorAll: () => [],
    querySelector: () => null,
    getElementById: () => null,
    createElement: (t) => fakeNode(t),
    addEventListener: () => {},
    execCommand: () => true,
  },
};
ctx.window = ctx;
ctx.self = ctx;
ctx.globalThis = ctx;
ctx.location = { origin: 'https://eatdanville.com', pathname: '/', search: '', hash: '' };
ctx.history = { replaceState: () => {} };
ctx.matchMedia = () => ({ matches: false, addEventListener() {}, addListener() {} });
ctx.CustomEvent = class CustomEvent {
  constructor(type, init) { this.type = type; this.detail = init && init.detail; }
};
ctx.dispatchEvent = (e) => { dispatched.push(e); return true; };
ctx.addEventListener = () => {};
ctx.EAT_DATA = {
  site: { corner: site.corner, parking: site.parking, landmarks: site.landmarks, walking_note: site.walking_note, hashtag: site.hashtag, sponsors: site.sponsors },
  restaurants,
  categories,
};

vm.createContext(ctx);
vm.runInContext(read('src/js/hours.js'), ctx, { filename: 'hours.js' });
vm.runInContext(read('src/js/planner.js'), ctx, { filename: 'planner.js' });

const H = ctx.EatHours;
const P = ctx.EatPlanner;

// ---------- harness ----------
let pass = 0;
const failures = [];
function test(name, fn) {
  try { fn(); pass += 1; console.log('  ok   ' + name); }
  catch (e) { failures.push(name); console.log('  FAIL ' + name + '\n       ' + (e && e.message)); }
}

function openAt(r, day, min) {
  const spans = H.spans(r.hours, day).concat(r.bar_hours ? H.spans(r.bar_hours, day) : []);
  return spans.some((s) => min >= s.open && min < s.close);
}
const bySlug = Object.fromEntries(restaurants.map((r) => [r.slug, r]));
const NO_DASH = /[\u2013\u2014]/;

console.log('EatPlanner smoke test');

test('exports exactly { init, plan, render }', () => {
  assert.deepEqual(Object.keys(P).sort(), ['init', 'plan', 'render']);
  assert.equal(typeof P.init, 'function');
  assert.equal(typeof P.plan, 'function');
  assert.equal(typeof P.render, 'function');
});

test('init() is a no-op and does not throw when the DOM hooks are absent', () => {
  P.init();
  P.init();
});

// ---- ask 1 ----
const a = P.plan({ time: '19:00', mood: 'date', prefs: ['dessert'], day: 'fri' });
test('ask 1: 7 PM Friday date night returns two different restaurants', () => {
  assert.ok(a.dinner, 'no dinner stop');
  assert.ok(a.nightcap, 'no nightcap stop');
  assert.notEqual(a.dinner.slug, a.nightcap.slug);
});
test('ask 1: the nightcap is open at 20:45 on Friday', () => {
  assert.equal(a.nightcap.at, 20 * 60 + 45);
  assert.equal(a.nightcap.atText, '8:45 PM');
  assert.ok(openAt(bySlug[a.nightcap.slug], 'fri', 20 * 60 + 45), a.nightcap.name + ' is not open at 20:45 Friday');
  assert.ok(a.nightcap.closes - a.nightcap.at >= 30, 'nightcap window shorter than 30 minutes');
});
test('ask 1: the dinner kitchen holds 75 minutes at 19:00', () => {
  const spans = H.spans(bySlug[a.dinner.slug].hours, 'fri');
  assert.ok(spans.some((s) => s.open <= 19 * 60 && s.close - 19 * 60 >= 75), 'dinner kitchen runway too short');
});
test('ask 1: both stops carry explainable reasons', () => {
  assert.ok(Array.isArray(a.dinner.reasons) && a.dinner.reasons.length >= 1, 'dinner has no reasons');
  assert.ok(Array.isArray(a.nightcap.reasons) && a.nightcap.reasons.length >= 1, 'nightcap has no reasons');
  assert.ok(a.dinner.reasons.every((r) => typeof r === 'string' && r.length > 4));
  assert.ok(!NO_DASH.test(a.dinner.reasons.join(' ') + a.nightcap.reasons.join(' ')), 'a reason carries a long dash');
});
test('ask 1: walkMin is a real one minute crossing', () => {
  assert.equal(a.walkMin, 1);
});

// ---- ask 2 ----
const b = P.plan({ time: '21:00', mood: 'solo', prefs: [], day: 'mon' });
test('ask 2: 9 PM Monday degrades to a single stop with a note', () => {
  assert.ok(b.dinner, 'no stop at all');
  assert.ok(['rancho-cantina', 'kaias'].includes(b.dinner.slug), 'unexpected stop ' + b.dinner.slug);
  assert.ok(b.notes.length >= 1, 'no note explaining the degrade');
  assert.ok(!NO_DASH.test(b.notes.join(' ')));
});
test('ask 2: the note names the closures honestly', () => {
  const text = b.notes.join(' ');
  assert.match(text, /Only Rancho Cantina is open at 9:00 PM on Mondays/);
  assert.ok(/Incontro is closed Mondays\./.test(text) || /closes at/.test(text), 'no closure detail: ' + text);
});
test('ask 2: nothing is proposed that is actually shut', () => {
  assert.ok(openAt(bySlug[b.dinner.slug], 'mon', 21 * 60), 'the stop is closed at 21:00 Monday');
  if (b.nightcap) assert.ok(openAt(bySlug[b.nightcap.slug], 'mon', 21 * 60 + 105));
});

// ---- ask 3 ----
const c = P.plan({ time: '20:00', mood: 'group', prefs: ['tiki'], day: 'sat' });
test('ask 3: 8 PM Saturday group with tiki puts Kaia\'s in the plan', () => {
  const slugs = [c.dinner && c.dinner.slug, c.nightcap && c.nightcap.slug].filter(Boolean);
  assert.ok(slugs.includes('kaias'), 'Kaia\'s missing from ' + slugs.join(', '));
});
test('ask 3: both Saturday stops are open when they are booked', () => {
  assert.ok(openAt(bySlug[c.dinner.slug], 'sat', 20 * 60));
  if (c.nightcap) assert.ok(openAt(bySlug[c.nightcap.slug], 'sat', 20 * 60 + 105));
});

// ---- robustness ----
test('plan() survives junk input and missing input', () => {
  const r1 = P.plan();
  const r2 = P.plan({ time: 'nonsense', day: 'blursday', mood: 'wat', prefs: 'nope,tiki' });
  [r1, r2].forEach((r) => {
    assert.ok(r && typeof r === 'object');
    assert.ok(Array.isArray(r.notes));
    assert.equal(typeof r.walkMin, 'number');
  });
  assert.equal(r2.time, '7:00 PM');
});

test('every hour chip on every day returns a usable answer', () => {
  ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'today'].forEach((day) => {
    ['18:00', '19:00', '20:00', '21:00'].forEach((time) => {
      ['', 'date', 'group', 'solo', 'show'].forEach((mood) => {
        const r = P.plan({ time, mood, prefs: ['dessert', 'patio'], day });
        assert.ok(r.dinner || r.notes.length, 'silent empty plan for ' + [day, time, mood].join('/'));
        if (r.dinner && r.nightcap) assert.notEqual(r.dinner.slug, r.nightcap.slug);
        assert.ok(!NO_DASH.test(JSON.stringify(r.notes)), 'long dash in notes for ' + [day, time, mood].join('/'));
      });
    });
  });
});

// ---- render ----
dispatched = [];
const html = P.render(a, resultEl);

test('render writes the contract markup into the target', () => {
  assert.equal(resultEl.innerHTML, html);
  assert.match(html, /<div class="itin">/);
  assert.equal((html.match(/class="stop"/g) || []).length, 2);
  assert.match(html, /<div class="when">7 PM<small>Dinner<\/small><\/div>/);
  assert.match(html, /<small>Nightcap<\/small>/);
  assert.match(html, /<div class="walk"><span class="ico">/);
  assert.match(html, /1 min across the corner/);
  assert.match(html, /class="planner-actions"/);
  assert.match(html, /Times use each restaurant's posted hours\. Reserve to be sure\./);
});

test('render uses the Phosphor person-simple-walk path, not a hand drawn icon', () => {
  const phosphor = fs.readFileSync(path.join(ROOT, 'node_modules/@phosphor-icons/core/assets/regular/person-simple-walk.svg'), 'utf8');
  const d = phosphor.match(/ d="([^"]+)"/)[1];
  assert.ok(html.includes(d), 'walk icon path does not match the Phosphor source');
  assert.ok(html.includes('aria-hidden="true"'));
  assert.ok(html.includes('fill="currentColor"'));
});

test('stop links are tracked and keyboard reachable anchors', () => {
  assert.match(html, /data-track="plan" data-slug="/);
  assert.match(html, /href="\/r\/[a-z-]+\/"/);
  assert.ok(html.includes('rel="noopener"'));
});

test('the calendar action is an anchor with download="danville-night.ics"', () => {
  assert.match(html, /<a class="btn btn-accent btn-sm" href="blob:eat-danville-fake" download="danville-night\.ics" data-plan-ics>/);
});

test('render escapes data through the local esc helper', () => {
  const kaias = html.includes('Kaia&#39;s') || html.includes('&amp;');
  assert.ok(kaias, 'restaurant name with an ampersand or apostrophe was not escaped');
  assert.ok(!/<h4>[^<]*&(?!amp;|#39;|quot;|lt;|gt;)/.test(html), 'raw ampersand in a heading');
});

test('rendered markup carries no long dashes', () => {
  assert.ok(!NO_DASH.test(html));
});

test('render dispatches eat:plan', () => {
  const ev = dispatched.filter((e) => e.type === 'eat:plan');
  assert.equal(ev.length, 1);
  assert.equal(ev[0].detail.plan.dinner.slug, a.dinner.slug);
  assert.equal(ev[0].detail.reduced, false);
});

test('render never throws without a target', () => {
  P.render(a, null);
  P.render(null, resultEl);
});

// ---- the .ics ----
test('the .ics holds two VEVENTs on the same Friday, 90 and 60 minutes', () => {
  assert.ok(lastBlob, 'no calendar blob was built');
  assert.equal(lastBlob.type, 'text/calendar;charset=utf-8');
  const ics = lastBlob.text;
  assert.equal((ics.match(/BEGIN:VEVENT/g) || []).length, 2);
  assert.equal((ics.match(/END:VEVENT/g) || []).length, 2);
  assert.match(ics, /^BEGIN:VCALENDAR\r\nVERSION:2\.0/);
  assert.match(ics, /END:VCALENDAR\r\n$/);
  assert.ok(!/DTSTART:[0-9T]+Z/.test(ics), 'DTSTART must be floating local time');

  const starts = [...ics.matchAll(/DTSTART:(\d{8})T(\d{2})(\d{2})00/g)];
  const ends = [...ics.matchAll(/DTEND:(\d{8})T(\d{2})(\d{2})00/g)];
  assert.equal(starts.length, 2);
  assert.equal(starts[0][1], starts[1][1], 'the two stops are on different dates');

  const mins = (m) => Number(m[2]) * 60 + Number(m[3]);
  assert.equal(mins(starts[0]), 19 * 60);
  assert.equal(mins(ends[0]) - mins(starts[0]), 90);
  assert.equal(mins(starts[1]), 20 * 60 + 45);
  assert.equal(mins(ends[1]) - mins(starts[1]), 60);

  const iso = starts[0][1];
  const d = new Date(Number(iso.slice(0, 4)), Number(iso.slice(4, 6)) - 1, Number(iso.slice(6, 8)));
  assert.equal(d.getDay(), 5, 'the calendar day is not a Friday');
  assert.ok(d >= new Date(new Date().getFullYear(), new Date().getMonth(), new Date().getDate()), 'the calendar day is in the past');

  assert.match(ics, /SUMMARY:Dinner at /);
  assert.match(ics, /SUMMARY:Nightcap at /);
  assert.match(ics, /LOCATION:[^\r\n]*Hartz Ave\\, Danville\\, CA/);
  assert.ok(ics.split('\r\n').every((l) => l.length <= 75), 'an unfolded line is longer than 75 octets');
  assert.ok(!NO_DASH.test(ics));
});

// ---- copy and share ----
test('Copy plan writes the plain text plan and toasts', async () => {
  copied = null;
  let toasted = null;
  ctx.EatToast = (m) => { toasted = m; };
  resultNodes['[data-plan-copy]'].click();
  await new Promise((r) => setTimeout(r, 0));
