  );
  assert.equal(toasted, 'Copied');
});

test('Share copies the state URL when navigator.share is missing', async () => {
  copied = null;
  resultNodes['[data-plan-share]'].click();
  await new Promise((r) => setTimeout(r, 0));
  const d = ctx.EatHours.now().day === 'fri' ? 'today' : 'fri';
  assert.equal(copied, 'https://eatdanville.com/?t=19:00&m=date&p=dessert&d=' + d + '#plan');
});

test('Share uses navigator.share when it exists', async () => {
  let shared = null;
  ctx.navigator.share = (payload) => { shared = payload; return Promise.resolve(); };
  copied = null;
  resultNodes['[data-plan-share]'].click();
  await new Promise((r) => setTimeout(r, 0));
  assert.ok(shared, 'navigator.share was not called');
  assert.match(shared.url, /\?t=19:00&m=date&p=dessert&d=/);
  assert.match(shared.text, /^7:00 PM dinner at /);
  assert.equal(copied, null, 'it copied as well as shared');
  delete ctx.navigator.share;
});

// ---- learning hook ----
test('EatSearch.boost is folded into the score when the model is present', () => {
  const plain = P.plan({ time: '19:00', mood: '', prefs: [], day: 'fri' });
