content.content:
175:.walk-label { background: var(--surface); color: var(--ink); border: 1px solid var(--line); border-radius: var(--r-pill); padding: 2px 8px; font-size: 11px; font-weight: 700; white-space: nowrap; box-shadow: var(--shadow-sm); }
176:.walk-label-wrap { background: transparent; border: 0; }
180:.planner { display: grid; grid-template-columns: minmax(280px, 0.9fr) 1.3fr; overflow: hidden; }
