187:.itin { display: grid; position: relative; }
188:.stop { display: grid; grid-template-columns: 64px 1fr; gap: 1rem; align-items: start; padding: 1rem 0; border-bottom: 1px solid var(--line); }
189:.stop:last-child { border-bottom: 0; }
190:.stop .when { font-family: var(--font-display); font-weight: 600; font-size: 1.15rem; letter-spacing: -0.02em; line-height: 1.1; padding-top: 0.2rem; }
191:.stop .when small { display: block; font-family: var(--font-body); font-weight: 600; font-size: 0.68rem; letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-3); margin-top: 0.25rem; }
192:.stop .what { display: grid; gap: 0.35rem; }
193:.stop .what h4 { font-size: 1.2rem; }
194:.stop .what p { color: var(--ink-2); font-size: 0.9375rem; }
