196:.stop .thumb img { width: 100%; height: 100%; object-fit: cover; }
197:.stop .links { display: flex; flex-wrap: wrap; gap: 0.4rem; margin-top: 0.3rem; }
198:.walk { display: flex; align-items: center; gap: 0.6rem; padding: 0.4rem 0; color: var(--ink-3); font-size: 0.8125rem; font-weight: 600; }
199:.walk .ico { color: var(--accent); }
200:.planner-actions { display: flex; flex-wrap: wrap; gap: 0.5rem; }
